@_mutmut_mutated(mutants_x_main__mutmut)
def main(argv: list[str] | None = None) -> int:
    """``tc-fitness`` console entrypoint.

    Subcommands:

    * ``run`` — load ``[tool.tc_fitness]`` and run the declared gate.
      ``--repo-root`` overrides CWD; ``--only ID`` runs a subset of steps;
      ``--gate ID`` targets a single fitness rule inside a catalogue step;
      ``--staged`` runs the ``<60s`` smoke tier (catalogue steps in sound
      per-rule ``--staged`` selection; ``skip_when_staged`` legs dropped);
      ``--changed-files-from PATH`` runs the same smoke tier against a CI
      supplied PR-diff file list.
    """
    arguments = list(sys.argv[1:] if argv is None else argv)
    if arguments and arguments[0] == "assure-coverage":
        from tc_fitness.coverage_transaction import main as coverage_main

        return coverage_main(arguments[1:])
    if arguments and arguments[0] == "mutation":
        from tc_fitness.mutation_assurance import main as mutation_main

        return mutation_main(arguments[1:])
    parser = argparse.ArgumentParser(
        prog="tc-fitness",
        description="The single runnable quality gate — local == CI by construction.",
    )
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("assure-coverage", help="fresh exact-base/candidate self-coverage transaction")
    sub.add_parser("mutation", help="produce or verify exact-candidate native mutation assurance")
    run_p = sub.add_parser("run", help="run the repo's declared [tool.tc_fitness] gate")
    run_p.add_argument("--contract", type=Path, help="execute a check-contract manifest case")
    run_p.add_argument("--case", help="case id within --contract")
    run_p.add_argument("--ledger", type=Path, help="write structured check-case evidence")
    run_p.add_argument(
        "--repo-root",
        default=None,
        help="repo root holding the gate config (default: CWD)",
    )
    run_p.add_argument(
        "--only",
        action="append",
        metavar="ID",
        help="run only the named step id(s) (repeatable)",
    )
    run_p.add_argument(
        "--gate",
        metavar="ID",
        help="target one fitness rule by id inside the catalogue step",
    )
    run_p.add_argument(
        "--staged",
        action="store_true",
        help="the <60s smoke tier: run catalogue steps in sound per-rule --staged "
        "mode and drop steps flagged skip_when_staged (the expensive full-tree legs)",
    )
    run_p.add_argument(
        "--changed-files-from",
        metavar="PATH",
        help="the <60s CI smoke tier: run staged selection against a newline-delimited changed-file list",
    )
    run_p.add_argument(
        "--shard",
        metavar="I/N",
        help="run shard i of N (e.g. --shard 2/4): append each opted-in step's "
        "shard_args (with {index}/{total} substituted) to its command and set "
        "COVERAGE_FILE=.coverage.<i> so a downstream `coverage combine` merges the "
        "shards. Steps without shard_args are untouched.",
    )
    run_p.add_argument(
        "--tier",
        metavar="NAME",
        help="run only steps whose `tags` include NAME (e.g. smoke/full/nightly); "
        "composes with --only, --staged and --changed-files-from",
    )
    args = parser.parse_args(argv)

    contract_mode = any(value is not None for value in (args.contract, args.case, args.ledger))
    if contract_mode:
        if any(value is None for value in (args.contract, args.case, args.ledger)):
            run_p.error("--contract, --case and --ledger are required together")
        if any(
            (
                args.repo_root is not None,
                args.only,
                args.gate,
                args.staged,
                args.changed_files_from,
                args.shard,
                args.tier,
            )
        ):
            run_p.error("contract arguments cannot be combined with ordinary gate options")
        from tc_fitness.check_contract_execution import execute_contract_case
        from tc_fitness.check_contracts import CheckContractError

        try:
            return execute_contract_case(args.contract.resolve(), args.case, args.ledger.resolve())
        except (CheckContractError, OSError) as exc:
            print(f"FAIL check contract: {exc}", file=sys.stderr)
            return 2

    repo_root = Path(args.repo_root or ".").resolve()
    try:
        cfg = load_config(repo_root)
    except GateConfigError as exc:
        print(f"{_RED}FAIL tc-fitness run{_RESET} — {exc}", file=sys.stderr)
        return 2
    try:
        changed_files = (
            paths_from_file(Path(args.changed_files_from).resolve()) if args.changed_files_from else None
        )
    except OSError as exc:
        print(
            f"{_RED}FAIL --changed-files-from{_RESET} - cannot read {args.changed_files_from}: {exc}",
            file=sys.stderr,
        )
        return 2
    try:
        shard = _parse_shard(args.shard) if args.shard else None
    except ValueError as exc:
        print(f"{_RED}FAIL --shard{_RESET} - {exc}", file=sys.stderr)
        return 2

    outcome = run_gate(
        cfg,
        repo_root,
        only=args.only,
        gate_id=args.gate,
        staged=bool(args.staged),
        changed_files=changed_files,
        shard=shard,
        tier=args.tier,
    )
    return outcome.exit_code


